class KeyTransform(FieldTransform):
    lookup_name = 'key'

    def get_prep_lookup(self, value):
        # Key transforms are often used with other transforms,
        # e.g. "?name__contains=foo". We must extract the field object
        # first, then apply the lookup.
        # Check if the object is a key transform
        if isinstance(value, KeyTransform):
            return value

        # Return the field object
        return Field.objects.get(pk=value.pk)

