class KeyTransformIn(lookups.In):
    lookup_name = 'in'

    def process_lhs(self, queryset, connection):
        lhs, lhs_params = super().process_lhs(queryset, connection)
        # Key transforms might be nested, so we resolve them against the
        # same queryset, applying any necessary subquery SQL.
        return (lhs.resolve_expression(queryset, connection, allow_joins=True),
                lhs_params)

    def process_rhs(self, queryset, connection):
        return self.process_lhs(queryset, connection)

    def get_db_prep_lookup(self, value, connection):
        value = super().get_db_prep_lookup(value, connection)
        # If the right side is a list/tuple of values, it can be
        # passed directly to database.
        if isinstance(value, (list, tuple)):
            return value
        # Otherwise if it's a single value, it can be handled by the
        # database.
        return [value]

    def as_sql(self, queryset, connection):
        # Key transforms always need to be resolved as part of the main query,
        # not as subqueries.
        lhs, params = self.process_lhs (queryset, connection)
        rhs, rhs_params = self.process_rhs(queryset, connection)
        params.extend(rhs_params)

        # We use the database's built-in IN lookup.
        return connection.ops.lookup_cast(
            self.lookup_name,
            self.lhs.output_field.get_db_prep_value(rhs, connection=connection), # type: ignore
            params,
        ).as_sql(connection)


