def is_classmethod_property(obj):
    return isinstance(obj, classmethod) and hasattr(obj.__get__(None, None), '__doc__')


class ClassPropertyDocumenter(object):
    objtype = 'attribute'

    def __init__(self, *args, **kwargs):
        pass

    def add_documenter(self, add_documenter_func, **kwargs):
        add_documenter_func(self, **kwargs)

    def parse_name(self, name, documenter):
        return name

    def document_members(self, documenter, members, modscope, options, **kwargs):
        source_name = documenter.parse_name(documenter.modscope, documenter.name)
        parent = documenter.get_object_source(documenter.modscope, documenter.name)

        for name, obj in inspect.getmembers(parent):
            if name.startswith('_') and not name.startswith('__'):
                continue

            if is_classmethod_property(obj):
                docstring = getattr(obj.__get__(None, None), '__doc__', None)
                documenter.document_member(name, obj, documenter.modscope, options, docstring)


def setup(app):
    app.add_autodoc_after_directive_hook(ClassPropertyDocumenter)
    app.connect('autodoc-skip-member', skip_member_handler)
    return {'version': '0.1'}

def skip_member_handler(app, what, name, obj, skip, options):
    if is_classmethod_property(obj):
        return False
    return skip

