class EvaluateFalseTransformer(ast.NodeTransformer):
    def __init__(self):
        self.evaluate = False

    def visit_Compare(self, node):
        if not isinstance(node.left, ast.Constant):
            return node
        if not all(isinstance(comp, ast.Constant) for comp in node.comparators):
            return node

        left_val = node.left.value
        values = [comp.value for comp in node.comparators]
        ops = node.ops

        result = True
        for i in range(len(ops)):
            op = ops[i]
            if isinstance(op, ast.Lt):
                result = result and (left_val < values[i])
            elif isinstance(op, ast.Gt):
                result = result and (left_val > values[i])
            elif isinstance(op, ast.LtE):
                result = result and (left_val <= values[i])
            elif isinstance(op, ast.GtE):
                result = result and (left_val >= values[i])
            elif isinstance(op, ast.Eq):
                result = result and (left_val == values[i])
            elif isinstance(op, ast.NotEq):
                result = result and (left_val != values[i])
            else:
                return node  # Not a supported comparison operator
            left_val = values[i]  # Update left_val for chained comparisons
        return ast.Constant(value=result)

class EvaluateFalseTransformer(ast.NodeTransformer):
    def __init__(self):
        self.evaluate = False

    def visit_Lambda(self, node):
        # Lambdas are special because they can be used to set evaluate=False in arguments
        # e.g. MyFunc(lamb x: x+1, evaluate=False)
        # Here, we want to ensure that the arguments are not evaluated
        # in case they are set to evaluate=False
        return ast.copy_location(ast.Lambda(node.args, self.visit(node.body)), node)

def visit_Call(self, node):
    # Check if the function being called is a SymPy function that supports evaluate=False
    # This example checks for Add and Mul, but you can extend it to other functions
    if isinstance(node.func, ast.Name) and node.func.id in ('Add', 'Mul'):
        new_args = []
        for i, arg in enumerate(node.args):
            if i == len(node.args) - 1 and isinstance(arg, ast.Constant) and arg.value is False:
                # This is the evaluate=False argument
                new_args.append(arg)
            else:
                # Recursively visit other arguments
                new_args.append(self.visit(arg))
        return ast.copy_location(ast.Call(node.func, new_args, node.keywords), node)
    else:
        # Default behavior: visit children nodes
        return self.generic_visit(node)
